import{_ as i,o as a,c as e,a0 as t}from"./chunks/framework.KrHIIkJd.js";const k=JSON.parse('{"title":"命令添加技能","description":"","frontmatter":{},"headers":[],"relativePath":"guide/command-add.md","filePath":"guide/command-add.md","lastUpdated":1786781926000}'),l={name:"guide/command-add.md"};function n(o,s,d,h,p,r){return a(),e("div",null,[...s[0]||(s[0]=[t('<h1 id="命令添加技能" tabindex="-1">命令添加技能 <a class="header-anchor" href="#命令添加技能" aria-label="Permalink to &quot;命令添加技能&quot;">​</a></h1><p>用一条命令从 GitHub 仓库安装技能,无需手动下载复制。</p><h2 id="使用方式" tabindex="-1">使用方式 <a class="header-anchor" href="#使用方式" aria-label="Permalink to &quot;使用方式&quot;">​</a></h2><p>「新建技能」→ 切换到「命令添加」,粘贴命令后点「解析并获取」:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/humanlayer/skills</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show-me</span></span></code></pre></div><p>支持的来源写法:</p><ul><li>完整命令:<code>npx skills add &lt;来源&gt; [--skill &lt;名字&gt;]</code></li><li>GitHub 链接:<code>https://github.com/owner/repo</code>(支持 <code>/tree/分支/子路径</code>)</li><li>简写:<code>owner/repo</code>、<code>owner/repo/技能目录</code></li><li>SSH 形式:<code>git@github.com:owner/repo.git</code></li></ul><div class="tip custom-block"><p class="custom-block-title">仅支持 GitHub 公开仓库</p><p>通过 GitHub API + raw 文件下载实现,未认证时 API 限流约 60 次/小时,日常使用足够。</p></div><h2 id="流程" tabindex="-1">流程 <a class="header-anchor" href="#流程" aria-label="Permalink to &quot;流程&quot;">​</a></h2><ol><li><strong>解析</strong>:识别仓库、分支、子路径与 <code>--skill</code> 指定的技能名</li><li><strong>列技能</strong>:仓库含多个技能时列出供选择(name + 描述 + 文件数);<code>--skill</code> 命中或仓库只有一个技能时自动选中</li><li><strong>下载预览</strong>:SKILL.md 与全部辅助文件下载到内存缓存,表单预填名字/描述/正文,均可修改</li><li><strong>AI 解读</strong>:配置了 DeepSeek API Key 时自动读取技能内容,生成标题、一句话描述与摘要并预填(可「重新解读」)</li><li><strong>选择目标</strong>:安装到哪些 agent——<strong>全部或单个任选</strong>(与同步弹窗同款),同名冲突需勾选覆盖</li><li><strong>安装</strong>:SKILL.md 按表单内容重建,辅助文件原样落盘;采用 staging → rename 原子替换,中途失败不留半成品;结果按 agent 逐条汇总</li></ol><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><p>从 <code>vercel-labs/skills</code> 安装单个技能:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vercel-labs/skills</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> some-skill</span></span></code></pre></div><p>指定分支与子路径:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/owner/repo/tree/main/skills/my-skill</span></span></code></pre></div>',15)])])}const g=i(l,[["render",n]]);export{k as __pageData,g as default};
